"""Readwise export books/highlights and Reader documents to Throughline messages.

Whose words are whose:

* A highlight's text was written by the book's author; the owner only chose
  it. Highlight messages are authored by the book's author
  (``system: readwise, kind: author``) with ``author_kind: other`` and
  ``selected_by: owner``.
* Highlight notes and a book's ``document_note`` are the owner's own words.
  They are separate messages (``entry_type: note``, ``author_kind: owner``,
  authored by the owner account) in the same book thread.
* Reader's ``summary`` can be generated by Ghostreader (an AI model) or be the
  publisher's description, so it never enters ``content`` and is kept in the
  ``summary`` field, marked with ``summary_author_kind: agent``.
"""

from .common import compact, field_list, fields_for, integer, iso, link, number, parse_time

HIGHLIGHTS = "readwise.highlights"
BOOKS = "readwise.books"
READER = "readwise.reader"
LINK_TYPES = ["part_of", "annotates", "created_by", "describes", "saved"]

SHARED = [
    "service", "source_kind", "event_type", "media_type", "title", "creator",
    "creators", "native_id", "native_ids", "url", "detail", "timing_basis",
    "time_precision", "source", "author_kind", "mapping_revision",
]
TAGS = ("json", "Tag names")
HIGHLIGHT_EXTRA = {
    "entry_type": ("text", "highlight (the author's passage) or note (the owner's own note)"),
    "selected_by": ("text", "owner when the owner selected someone else's words (highlights)"),
    "book_id": ("text", "Readwise user_book_id of the book or article"),
    "highlight_id": ("text", "Readwise highlight ID (notes: the highlight they annotate)"),
    "origin": ("text", "Where Readwise got it (kindle, reader, instapaper, ...)"),
    "location": ("integer", "Position of the highlight in the book"),
    "location_type": ("text", "Unit of location (page, location, order, time_offset)"),
    "color": ("text", "Highlight colour"),
    "tags": TAGS,
    "is_favorite": ("boolean", "The owner favourited the highlight"),
    "is_discard": ("boolean", "The owner discarded the highlight in review"),
    "has_note": ("boolean", "The highlight has an owner note (its own message)"),
}
BOOK_EXTRA = {
    "book_id": HIGHLIGHT_EXTRA["book_id"],
    "origin": HIGHLIGHT_EXTRA["origin"],
    "category": ("text", "Readwise category (books, articles, tweets, podcasts, supplementals)"),
    "tags": TAGS,
    "highlight_count": ("integer", "Highlights Readwise holds for this source"),
    "has_document_note": ("boolean", "The owner wrote a document note (its own message)"),
}
READER_EXTRA = {
    "progress": ("number", "Fraction of the work completed, 0 to 1"),
    "is_finished": ("boolean", "Archived in Reader or read to at least 99%"),
    "added_at": ("timestamp", "When the work was added to a library or list"),
    "location": ("text", "Reader location: new, later, shortlist, archive or feed"),
    "category": ("text", "Reader category (article, email, rss, pdf, epub, tweet, video)"),
    "site_name": ("text", "Publishing site"),
    "word_count": ("integer", "Words in the document"),
    "tags": TAGS,
    "first_opened_at": ("timestamp", "First time the owner opened it"),
    "last_opened_at": ("timestamp", "Last time the owner opened it"),
    "summary": (
        "text",
        "Reader's summary: may be AI-generated (Ghostreader) or the publisher's "
        "description, never the owner's words",
    ),
    "summary_author_kind": ("text", "agent when a summary is present (treat as model-generated)"),
}
# progress / is_finished / added_at come from the shared vocabulary.
READER_SHARED = ["progress", "is_finished", "added_at"]
HIGHLIGHT_FIELDS = field_list(SHARED, HIGHLIGHT_EXTRA)
BOOK_FIELDS = field_list(SHARED, BOOK_EXTRA)
READER_FIELDS = field_list(
    SHARED + READER_SHARED, {k: v for k, v in READER_EXTRA.items() if k not in READER_SHARED}
)

BOOK_MEDIA = {
    "books": "book",
    "articles": "article",
    "tweets": "tweet",
    "podcasts": "podcast",
    "supplementals": "other",
}
READER_MEDIA = {
    "article": "article",
    "rss": "article",
    "email": "email",
    "pdf": "document",
    "epub": "book",
    "tweet": "tweet",
    "video": "video",
}
FINISHED_PROGRESS = 0.99


def owner_author(settings):
    system, kind, value = settings["owner_identifier"].split(":", 2)
    return {
        "system": system,
        "kind": kind,
        "value": value,
        "display_name": settings.get("owner_name") or None,
    }


def author_of(book):
    name = (book.get("author") or "").strip() or "Unknown author"
    return {"system": "readwise", "kind": "author", "value": name, "display_name": name}


def tag_names(tags):
    """Readwise tags arrive as [{id, name}], [str] or (Reader) {name: {...}}."""
    if isinstance(tags, dict):
        return sorted(tags) or None
    names = [t.get("name") if isinstance(t, dict) else t for t in tags or []]
    return [n for n in names if n] or None


def book_title(book):
    return (book.get("readable_title") or book.get("title") or "").strip() or "Untitled"


def highlight_time(highlight):
    return parse_time(highlight.get("highlighted_at")) or parse_time(highlight.get("created_at"))


def first_highlight_time(book):
    times = [t for t in (highlight_time(h) for h in book.get("highlights") or []) if t]
    return min(times) if times else None


def book_ref(book):
    return {
        "kind": "work",
        "external_ref": f"readwise:book:{book['user_book_id']}",
        "name": book_title(book),
    }


def author_ref(name):
    return {"kind": "author", "external_ref": f"readwise:author:{name.casefold()}", "name": name}


def book_common(declared, book, **values):
    author = (book.get("author") or "").strip() or None
    return fields_for(
        declared,
        service="readwise",
        media_type=BOOK_MEDIA.get(book.get("category"), "other"),
        title=book_title(book),
        creator=author,
        creators=[author] if author else None,
        native_id=f"readwise:book:{book['user_book_id']}",
        url=book.get("source_url") or book.get("unique_url") or None,
        source="api",
        mapping_revision=1,
        **values,
    )


def book_ids(book):
    return compact(
        {
            "user_book_id": book["user_book_id"],
            "asin": book.get("asin"),
            "readwise_url": book.get("readwise_url"),
            "source_url": book.get("source_url"),
            "unique_url": book.get("unique_url"),
        }
    )


def thread_of(book):
    return {"external_id": f"readwise:book:{book['user_book_id']}", "title": book_title(book)}


def ref(message):
    return {"channel": message["channel"], "external_id": message["external_id"]}


def map_book(book, settings):
    """One export result to (messages, links) for both export channels.

    Books without any dated highlight are skipped: Readwise has no
    book-level timestamp to date them by."""
    if book.get("is_deleted"):
        return [], []
    first = first_highlight_time(book)
    if first is None:
        return [], []
    me = owner_author(settings)
    work = book_ref(book)
    messages, links = [], []
    author = (book.get("author") or "").strip()
    if author:
        links.append(link("created_by", work, author_ref(author)))
    highlights = sorted(
        book.get("highlights") or [], key=lambda h: (highlight_time(h) or first, str(h["id"]))
    )
    for h in highlights:
        when = highlight_time(h) or first
        note = (h.get("note") or "").strip()
        common = dict(
            book_id=str(book["user_book_id"]),
            highlight_id=str(h["id"]),
            origin=book.get("source"),
            native_ids=compact(dict(book_ids(book), highlight_id=h["id"], external_id=h.get("external_id"))),
            event_type="highlight",
            time_precision="source_mark" if highlight_time(h) else "first_seen",
        )
        message = {
            "channel": HIGHLIGHTS,
            "external_id": f"readwise:highlight:{h['id']}",
            "thread": thread_of(book),
            "happened_at": iso(when),
            "author": author_of(book),
            "content": (h.get("text") or "").strip() or "(highlight without text)",
            "fields": book_common(
                HIGHLIGHT_FIELDS,
                book,
                source_kind="highlight",
                entry_type="highlight",
                selected_by="owner",
                author_kind="other",
                location=integer(h.get("location")),
                location_type=h.get("location_type"),
                color=h.get("color") or None,
                tags=tag_names(h.get("tags")),
                is_favorite=bool(h.get("is_favorite")),
                is_discard=bool(h.get("is_discard")),
                has_note=bool(note),
                timing_basis="When the owner highlighted the passage (created_at if unknown)",
                detail=compact({"end_location": h.get("end_location"), "highlight_url": h.get("url")}) or None,
                **common,
            ),
            "payload": dict(h, user_book_id=book["user_book_id"]),
        }
        messages.append(message)
        links.append(link("part_of", ref(message), work))
        if note:
            note_message = {
                "channel": HIGHLIGHTS,
                "external_id": f"readwise:highlight:{h['id']}:note",
                "thread": thread_of(book),
                "happened_at": iso(when),
                "author": me,
                "content": note,
                "fields": book_common(
                    HIGHLIGHT_FIELDS,
                    book,
                    source_kind="highlight_note",
                    entry_type="note",
                    author_kind="owner",
                    location=integer(h.get("location")),
                    location_type=h.get("location_type"),
                    tags=tag_names(h.get("tags")),
                    is_discard=bool(h.get("is_discard")),
                    timing_basis="Time of the highlight it annotates (Readwise does not date notes)",
                    **common,
                ),
                "payload": {
                    "highlight_id": h["id"],
                    "user_book_id": book["user_book_id"],
                    "note": h.get("note"),
                },
            }
            messages.append(note_message)
            links.append(link("annotates", ref(note_message), ref(message)))
    document_note = (book.get("document_note") or "").strip()
    if document_note:
        message = {
            "channel": HIGHLIGHTS,
            "external_id": f"readwise:book:{book['user_book_id']}:note",
            "thread": thread_of(book),
            "happened_at": iso(first),
            "author": me,
            "content": document_note,
            "fields": book_common(
                HIGHLIGHT_FIELDS,
                book,
                source_kind="document_note",
                event_type="highlight",
                entry_type="note",
                author_kind="owner",
                book_id=str(book["user_book_id"]),
                origin=book.get("source"),
                native_ids=book_ids(book),
                tags=tag_names(book.get("book_tags")),
                timing_basis="Earliest highlight of the book (Readwise does not date document notes)",
                time_precision="first_seen",
            ),
            "payload": {"user_book_id": book["user_book_id"], "document_note": book.get("document_note")},
        }
        messages.append(message)
        links.append(link("annotates", ref(message), work))
    count = len(book.get("highlights") or [])
    kind = BOOK_MEDIA.get(book.get("category"), "other")
    fields = book_common(
        BOOK_FIELDS,
        book,
        source_kind="book",
        event_type="library_added",
        author_kind="owner",
        book_id=str(book["user_book_id"]),
        origin=book.get("source"),
        category=book.get("category"),
        native_ids=book_ids(book),
        tags=tag_names(book.get("book_tags")),
        highlight_count=count,
        has_document_note=bool(document_note),
        timing_basis="Earliest highlight (Readwise has no book-level timestamp)",
        time_precision="first_seen",
        detail=compact({"cover_image_url": book.get("cover_image_url")}) or None,
    )
    entry = {
        "channel": BOOKS,
        "external_id": f"readwise:book:{book['user_book_id']}",
        "thread": {"external_id": "readwise:library", "title": "Readwise library"},
        "happened_at": iso(first),
        "author": me,
        "content": f"{fields['title']}"
        + (f" by {fields['creator']}" if fields["creator"] else "")
        + f" ({kind}, {count} highlight{'s' if count != 1 else ''} in Readwise)",
        "fields": fields,
        "payload": {k: v for k, v in book.items() if k != "highlights"},
    }
    messages.append(entry)
    links.append(link("describes", ref(entry), work))
    return messages, links


def map_document(doc, settings):
    """One Reader v3 document to (message, links); None for child records.

    Records with a parent_id are Reader highlights and notes; the v2 export
    already carries them (with their notes), so they are not duplicated."""
    if doc.get("parent_id"):
        return None
    when = parse_time(doc.get("saved_at")) or parse_time(doc.get("created_at"))
    if when is None:
        return None
    progress = number(doc.get("reading_progress"))
    summary = (doc.get("summary") or "").strip() or None
    author = (doc.get("author") or "").strip() or None
    title = (doc.get("title") or "").strip() or doc.get("url") or "Untitled"
    category = doc.get("category")
    fields = fields_for(
        READER_FIELDS,
        service="readwise",
        source_kind="reader_document",
        event_type="saved",
        media_type=READER_MEDIA.get(category, "other"),
        title=title,
        creator=author,
        creators=[author] if author else None,
        native_id=f"readwise:reader:{doc['id']}",
        native_ids=compact({"reader_id": doc["id"], "url": doc.get("url"), "source_url": doc.get("source_url")}),
        url=doc.get("source_url") or doc.get("url") or None,
        timing_basis="When the document was saved to Reader (created_at if unknown)",
        time_precision="source_mark",
        source="api",
        author_kind="owner",
        progress=progress,
        is_finished=doc.get("location") == "archive" or (progress or 0) >= FINISHED_PROGRESS,
        added_at=iso(when),
        location=doc.get("location"),
        category=category,
        site_name=doc.get("site_name") or None,
        word_count=integer(doc.get("word_count")),
        tags=tag_names(doc.get("tags")),
        first_opened_at=iso(parse_time(doc.get("first_opened_at"))),
        last_opened_at=iso(parse_time(doc.get("last_opened_at"))),
        summary=summary,
        summary_author_kind="agent" if summary else None,
        detail=compact(
            {
                "published_date": doc.get("published_date"),
                "image_url": doc.get("image_url"),
                "last_moved_at": doc.get("last_moved_at"),
                "reader_source": doc.get("source"),
            }
        )
        or None,
        mapping_revision=1,
    )
    day = when.date().isoformat()
    message = {
        "channel": READER,
        "external_id": f"readwise:reader:{doc['id']}",
        "thread": {"external_id": f"readwise:reader:day:{day}", "title": f"Reader saves {day}"},
        "happened_at": iso(when),
        "author": owner_author(settings),
        "content": f"Saved {title}"
        + (f" by {author}" if author else "")
        + (f" ({doc['site_name']})" if doc.get("site_name") else "")
        + " to Reader",
        "fields": fields,
        "payload": {k: v for k, v in doc.items() if k not in ("html_content",)},
    }
    work = {"kind": "work", "external_ref": f"readwise:reader:{doc['id']}", "name": title}
    links = [link("saved", ref(message), work)]
    if author:
        links.append(link("created_by", work, author_ref(author)))
    return message, links
